    'fc.help_body' => 'Управляет кодами быстрого набора с телефона (например, <code>*78</code>): «Не беспокоить» (DND), переадресация вызовов, групповой/направленный перехват вызова, прослушивание вызова, вход в очередь/выход из очереди (<code>*81&lt;queue id&gt;</code> / <code>*80&lt;queue id&gt;</code>), пауза / снятие с паузы в очереди (<code>*22&lt;break id&gt;</code> / <code>*23</code>).',
