    'cdr_reports.help_body' => 'Предоставляет подробную детализацию (CDR) всех входящих/исходящих вызовов, выполненных через AI PBX и колл-центр.',
    'cdr_reports.help_body2' => 'Каждая строка — один вызов: в столбце <b>Звонящий</b> — транк, через который он поступил, в столбце <b>Набранный</b> — маршрут и, если вызов покинул АТС, транк и переданный номер; <b>Ответил</b> — внутренний номер, принявший вызов. <b>Направление</b>: входящий, исходящий, внутренний или транк-транк (поступил через один транк и ушёл через другой без ответа внутреннего номера AiPBX). Разверните строку, чтобы увидеть путь переведённых вызовов. Фильтруйте по дате, статусу, внутреннему номеру, устройству, направлению и транку; прослушивайте или скачивайте записи.',
