    'asterisk_settings.rtp_section_title' => 'Настройки RTP (медиа)',
    'asterisk_settings.rtp_help_body' => 'Определяет диапазон портов для передачи звука (RTP) и то, отклоняет ли Asterisk звук, поступающий из неожиданного источника. Этот файл (<code>/etc/asterisk/rtp.conf</code>) теперь создаётся панелью; ручные изменения на сервере будут потеряны при следующем «Применить».',
    'asterisk_settings.field_rtp_start' => 'Начальный порт RTP',
    'asterisk_settings.rtp_start_help' => 'Начало диапазона портов, зарезервированного для аудиопотоков. Каждый одновременный вызов занимает порты из этого диапазона.',
