    'asterisk_settings.rtp_end_help' => 'Конец диапазона. coturn (TURN-ретранслятор) использует 13479-14999 — пересечение нарушает звук WebRTC и отклоняется при сохранении.',
    'asterisk_settings.field_rtp_strict' => 'Строгий RTP (strictrtp)',
    'asterisk_settings.rtp_strict_help' => 'Если включено, Asterisk молча отбрасывает звук, поступающий из любого источника, кроме изученного удалённого адреса/порта (защита от атак). Если удалённая АТС отправляет медиа с неожиданного порта, это вызывает скрытую неисправность «нет звука» без следов в журнале — для диагностики его можно временно отключить.',
