    'trunks.connection_mode_register' => 'Входящая регистрация (удалённая сторона регистрируется у нас)',
    'trunks.connection_mode_help' => 'По IP: удалённая сторона определяется по IP-адресу, а её контакт остаётся статическим — рекомендуемый режим для стороны с фиксированным IP в той же сети. Входящая регистрация: удалённая сторона отправляет нам SIP REGISTER, и её адрес определяется по этой регистрации. Этот режим требует имени пользователя и пароля; ими удалённая сторона аутентифицирует и регистрацию, и вызовы.',
    'trunks.connection_mode_warning' => 'Переключение в режим регистрации удаляет статический контакт: мы не сможем вызывать этот транк, ПОКА удалённая сторона не зарегистрируется у нас. Выполняйте это изменение синхронно с настройкой регистрации на удалённой стороне.',
