    'sound_packs.title' => 'Официальные звуковые пакеты Asterisk',
    'sound_packs.help_title' => 'Звуковые пакеты Asterisk',
    'sound_packs.help_body' => 'Загружает и устанавливает официальные системные голосовые сообщения и музыку на удержании Asterisk с <code>downloads.asterisk.org</code>. Каждый пакет — это один язык в одном формате; Asterisk воспроизводит формат, соответствующий кодеку вызова, а в противном случае выполняет перекодирование (g722 для G.722, ulaw/alaw для операторов связи).<br>- <strong>Core:</strong> системные сообщения, цифры, голосовая почта. <strong>Extra:</strong> дополнительные сообщения; сначала должен быть установлен пакет core для того же языка.<br>- <strong>Музыка на удержании (opsound):</strong> устанавливается в <code>/var/lib/asterisk/moh/opsound</code>; чтобы её воспроизводить, создайте класс MOH с именем <strong>opsound</strong> на вкладке «Музыка на удержании».<br>- <strong>Türkçe (AiPBX):</strong> собственные турецкие голосовые сообщения AiPBX (релиз на GitHub, проверка SHA256); язык по умолчанию — турецкий, поэтому их удаление отключит системные сообщения. При удалении удаляются только файлы, установленные пакетом.',
