    'ms_teams.guide_dr_title' => '1. Direct Routing (SBC / SIP-транк):',
    'ms_teams.guide_dr_desc' => 'Позволяет пользователям Teams совершать и принимать внутренние и внешние вызовы непосредственно с панели набора Teams на компьютере/мобильном устройстве. Требуется TLS (порт 5061), SRTP и действительный публичный SSL-сертификат (напр. Let\'s Encrypt).',
    'ms_teams.guide_webhook_title' => '2. Webhooks и уведомления в каналы:',
