    'certificates.help_body' => 'Портал (HTTPS), WebRTC TURNS и SIP-TLS/WSS используют один общий сертификат; изменения здесь применяются одновременно к Apache, coturn и Asterisk. <b>Let\'s Encrypt</b> бесплатен и продлевается автоматически; домен должен указывать на этот сервер, а порт 80 должен быть доступен из интернета. Если у Вашей организации есть сертификат, <b>загрузите его</b> (PEM или PFX); загруженные сертификаты не продлеваются автоматически, загрузите новый до истечения срока действия. При <b>самоподписанном</b> сертификате браузеры показывают предупреждение, а TURNS в браузерах не работает: у вызовов WebRTC через межсетевые экраны может не быть звука.',
