    'queue_reports.title' => 'Центр отчётов по очередям',
    'queue_reports.help_title' => 'Руководство по отчётам об очередях',
    'queue_reports.help_body' => 'Каждый вызов, попавший в очередь, учитывается один раз. <b>Отвечен</b>: соединён с оператором. <b>Потерян</b>: звонящий положил трубку во время ожидания или истекло время ожидания очереди. <b>Короткий отказ</b>: положил трубку в течение %d секунд; не учитывается в уровне обслуживания. <b>Уровень обслуживания</b>: доля вызовов, отвеченных в пределах целевого времени, от всех вызовов, кроме коротких отказов. <b>ASA</b>: среднее ожидание отвеченных вызовов. <b>AHT</b>: среднее время разговора. <b>Доля ответов</b> (оператор): как часто оператор отвечал, когда очередь его вызывала. <b>Перезвон</b>: потерянный вызов считается решённым, если позже на этот номер позвонили с внутреннего номера либо абонент позвонил снова и получил ответ. Данные берутся из журнала очередей Asterisk; отчёт можно скачать в формате PDF или Excel.',
