    'ai_tts.title' => 'Облачный TTS (синтез речи)',
    'ai_tts.help_title' => 'Руководство по облачному TTS',
    'ai_tts.help_body' => 'Преобразует текст в естественную речь с помощью облачных сервисов (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Прослушайте результат, скачайте его в MP3 или сохраните одним щелчком как <b>объявление</b>: оно будет преобразовано в формат Asterisk (WAV 8 кГц) и добавлено в раздел «Звуки и объявления» для IVR, входящих маршрутов и условий по времени (вступает в силу после применения). <b>Эти сервисы платные</b> и тарифицируются посимвольно; каждый синтез сохраняется в истории с количеством символов. Ключи доступа берутся из консоли каждого провайдера, хранятся в зашифрованном виде и больше никогда не отображаются на странице.',
    'ai_tts.tab_speak' => 'Синтез',
    'ai_tts.tab_providers' => 'Провайдеры',
    'ai_tts.providers_text' => 'Введите данные доступа к сервисам, которые Вы хотите использовать. Секретные ключи хранятся в зашифрованном виде; оставьте поле ключа пустым, чтобы сохранить текущий.',
    'ai_tts.configured' => 'Подключено',
    'ai_tts.not_configured' => 'Не настроено',
    'ai_tts.optional' => 'необязательно',
    'ai_tts.keep_secret' => 'введите новый ключ, чтобы изменить его',
    'ai_tts.provider_hint_google' => 'Google Cloud Console → APIs &amp; Services: включите «Cloud Text-to-Speech API»; используйте JSON-ключ сервисного аккаунта (IAM → Service Accounts → Keys → JSON) или ключ API. До %s символов на запрос; более длинные тексты разбиваются.',
    'ai_tts.provider_hint_polly' => 'В AWS IAM создайте ключ доступа для пользователя, у которого есть только «polly:SynthesizeSpeech» и «polly:DescribeVoices». До %s символов на запрос.',
    'ai_tts.provider_hint_azure' => 'Создайте ресурс «Speech» на портале Azure; ключ и регион (например, westeurope) находятся на его странице «Keys and Endpoint». До %s символов на запрос.',
    'ai_tts.provider_hint_elevenlabs' => 'ElevenLabs → Profile → API Keys. Голоса берутся из библиотеки голосов Вашей учётной записи и являются многоязычными. До %s символов на запрос.',
    'ai_tts.provider_hint_openai' => 'platform.openai.com → API keys. Набор голосов фиксирован, они говорят на любом языке; модель gpt-4o-mini-tts (или tts-1, tts-1-hd). До %s символов на запрос.',
