    'push.help_title' => 'Об архитектуре мобильных уведомлений',
    'push.help_intro' => 'Мобильный программный телефон AI PBX использует <strong>многоуровневую архитектуру уведомлений</strong>:',
    'push.help_layer0' => '<strong>Уровень 0 (без зависимостей - по умолчанию):</strong> постоянное соединение WSS, совместимая с Android 15 служба переднего плана <code>specialUse</code> и устойчивый к режиму Doze сторожевой таймер <code>AlarmManager</code>, который её перезапускает. Никакие внешние сервисы не нужны; вызовы поступают даже когда устройство бездействует или экран выключен.',
    'push.help_layer1' => '<strong>Уровень 1 (необязательно - Google FCM):</strong> дополнительная гарантия пробуждения на устройствах производителей с агрессивными ограничениями батареи (Xiaomi, Huawei...) или если пользователь смахнул приложение. <em>Срабатывает только когда у внутреннего номера нет активной регистрации SIP, поэтому для зарегистрированных номеров задержки нет.</em>',
    'push.help_no_fcm' => 'Если Вы не хотите использовать FCM, оставьте провайдер <strong>«Локальный (без зависимостей)»</strong>. В этом случае мобильное приложение вообще не обращается к Google по сети.',
