    'mailtpl.invite_new.subject' => '[{brand}] Ваша учётная запись создана - задайте пароль',
    'mailtpl.invite_new.body' => '<p>Здравствуйте, {name}!</p><p>Ваша учётная запись на АТС <strong>{brand}</strong> готова. Чтобы войти, задайте пароль с помощью кнопки ниже.</p>{account_details}{reset_button}<p>Если кнопка не работает, откройте эту ссылку: {reset_link}</p>{mobile_section}<p><em>Ссылка для пароля действует 48 часов и срабатывает один раз. Если вы не ожидали этого письма, обратитесь к системному администратору.</em></p>',
    'mailtpl.invite.subject' => '[{brand}] Ваша ссылка для входа и пароля',
    'mailtpl.invite.body' => '<p>Здравствуйте, {name}!</p><p>Вот новая ссылка, чтобы задать пароль для <strong>{brand}</strong>.</p>{account_details}{reset_button}<p>Если кнопка не работает, откройте эту ссылку: {reset_link}</p>{mobile_section}<p><em>Ссылка для пароля действует 48 часов и срабатывает один раз. Если вы её не запрашивали, обратитесь к системному администратору.</em></p>',
    'mailtpl.password_reset.subject' => '[{brand}] Сброс пароля',
    'mailtpl.password_reset.body' => '<p>Здравствуйте, {name}!</p><p>Для вашей учётной записи <strong>{username}</strong> запрошен сброс пароля.</p>{reset_button}<p>Если кнопка не работает, откройте эту ссылку: {reset_link}</p><p><em>Ссылка действует 30 минут. Если вы её не запрашивали, проигнорируйте это письмо; ваш пароль не изменится.</em></p>',
    'mailtpl.voicemail.subject' => 'Новое голосовое сообщение от {caller} ({duration})',
    'mailtpl.voicemail.body' => '<p>Здравствуйте, {name}!</p><p>В почтовом ящике <strong>{mailbox}</strong> новое голосовое сообщение.</p><ul><li><strong>От:</strong> {caller}</li><li><strong>Получено:</strong> {date}</li><li><strong>Длительность:</strong> {duration}</li></ul><p>Если запись прикреплена, её можно прослушать прямо здесь. Также её можно прослушать на портале ({portal_link}) или набрав *97.</p>',
    'mailtpl.fax_received.subject' => 'Получен новый факс - {department} ({did})',
    'mailtpl.fax_received.body' => '<p>Получен новый факс.</p><ul><li><strong>Подразделение:</strong> {department}</li><li><strong>Номер факса:</strong> {did}</li><li><strong>От:</strong> {caller}</li><li><strong>Страниц:</strong> {pages}</li><li><strong>Получено:</strong> {date}</li></ul><p>Факс прикрепляется в формате PDF, если эта функция включена. Все факсы находятся во входящих факсах: {portal_link}</p>',
    'mailtpl.fax_sent.subject' => 'Факс доставлен на {destination} (#{fax_id})',
    'mailtpl.fax_sent.body' => '<p>Ваш факс доставлен.</p><ul><li><strong>Кому:</strong> {destination}</li><li><strong>Страниц:</strong> {pages}</li><li><strong>Время:</strong> {date}</li></ul><p>Отправленные факсы: {portal_link}</p>',
