    'storage.help_title' => 'Где хранятся файлы чата',
    'storage.help_body' => '<p>Вложения чата, их миниатюры и изображения групп по умолчанию хранятся на диске сервера (<code>/var/lib/aipbx/chat_files</code>). С S3-совместимым хранилищем (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) они попадают в бакет, и большие файлы не занимают место на АТС.</p><p>Загрузки по-прежнему идут через службу чата, поэтому открыть файлы чата могут только его участники; бакет может оставаться закрытым. Файлы, сохранённые до переключения, по-прежнему отдаются с диска, пока Вы их не перенесёте. Настройки бакета проверяются перед сохранением.</p><p>Записи разговоров, голосовая почта и факсы остаются на локальном диске.</p>',
