    'netsvc.help_title' => 'Сетевые службы',
    'netsvc.help_body' => 'Настольные телефоны сами находят сервер автонастройки, если DHCP-сервер сообщает его адрес (опция 66). DHCP и TFTP включаются по отдельности. Если <strong>DHCP-сервер</strong> выключен, остаётся Ваш собственный DHCP-сервер: задайте на нём опции, перечисленные ниже. Если включён, AiPBX раздаёт адреса на одном интерфейсе или VLAN. <strong>TFTP-сервер</strong> отдаёт загруженные Вами загрузочные файлы и прошивки. Конфигурация каждого телефона (с паролем SIP) всегда отдаётся по HTTPS, никогда по TFTP.',
